<?php $names=['new'=>'Новая','confirmed'=>'Подтверждена','completed'=>'Завершена','cancelled'=>'Отменена']; ?>
<?php require __DIR__.'/shop-shell.php'; ?>
<h1><?= $tool==='orders'?'Заявки':'Перенос сайта' ?></h1>
<?php if($error):?><div class="notice error" role="alert"><?= e($error) ?></div><?php endif ?>
<?php if($tool==='transfer'):?>
<section class="form-panel"><h2>Выгрузить магазин</h2><p>Один ZIP с движком, каталогом, текстами и фотографиями. Распакуйте его на PHP-хостинге и создайте новый вход через /admin/install.</p><p>Доступы, ключи сервисов и данные покупателей остаются на этом сервере.</p><form method="post"><input type="hidden" name="csrf" value="<?= e($csrf) ?>"><button class="button primary" name="action" value="export">Скачать сайт ZIP</button></form></section>
<section class="form-panel"><h2>Загрузить контент</h2><p>Заменяет каталог, тексты и фотографии выгрузкой этой же версии. Вход, ключи и существующие заявки сохраняются. Перед заменой сервер делает полный резервный ZIP в data/backups/.</p><?php if($backup):?><div class="notice">Контент загружен. Резервная копия: <?= e($backup) ?></div><?php endif ?><form method="post" enctype="multipart/form-data" class="edit-form"><input type="hidden" name="csrf" value="<?= e($csrf) ?>"><input type="hidden" name="action" value="import"><label>Архив магазина<input type="file" name="file" accept=".zip" required></label><label><input type="checkbox" name="confirm" value="1" required> Заменить текущее содержимое</label><button class="button">Загрузить контент</button></form></section>
<?php elseif($order):?><p><a href="/admin/shop/orders">← Все заявки</a></p><section class="form-panel"><h2>Заявка №<?= $id ?></h2><p><?= e($order['created_at']) ?> UTC · <?= e($names[$order['status']]) ?></p><p><strong><?= e($order['customer_name']) ?></strong><br><?= e($order['customer_contact']) ?></p><p><?= nl2br(e($order['greeting'])) ?></p><div class="table-wrap"><table><thead><tr><th>Состав на момент заказа</th><th>Количество</th><th>Цена</th><th>Сумма</th></tr></thead><tbody><?php foreach(shop_query('SELECT * FROM shop_order_items WHERE order_id=? ORDER BY id',[$id]) as $i):?><tr><td><?= e($i['name_snapshot']) ?><small><?= e($i['sku_snapshot']) ?></small></td><td><?= (int)$i['quantity'] ?></td><td><?= e(shop_money((int)$i['unit_price_minor'],$order['currency']??'EUR')) ?></td><td><?= e(shop_money($i['quantity']*$i['unit_price_minor'],$order['currency']??'EUR')) ?></td></tr><?php endforeach ?></tbody></table></div><p class="total">Итого: <?= e(shop_money((int)$order['total_minor'],$order['currency']??'EUR')) ?></p><p class="muted">Согласие на связь: <?= e($order['consent_at']??'—') ?> UTC</p>
<?php $next=['new'=>['confirmed','cancelled'],'confirmed'=>['completed','cancelled'],'completed'=>[],'cancelled'=>[]][$order['status']];if($next):?><form method="post"><input type="hidden" name="csrf" value="<?= e($csrf) ?>"><input type="hidden" name="id" value="<?= $id ?>"><label>Следующий статус<select name="status"><?php foreach($next as $v):?><option value="<?= e($v) ?>"><?= e($names[$v]) ?></option><?php endforeach ?></select></label><button class="button primary">Сохранить статус</button></form><?php endif ?></section>
<?php else:?><form class="search" method="get"><label>Статус<select name="status"><option value="">Все</option><?php foreach($names as $v=>$n):?><option value="<?= e($v) ?>" <?= $status===$v?'selected':'' ?>><?= e($n) ?></option><?php endforeach ?></select></label><button class="button">Показать</button></form><p>Всего: <?= $total ?></p><div class="table-wrap"><table><thead><tr><th>Номер / дата UTC</th><th>Покупатель</th><th>Сумма</th><th>Статус</th></tr></thead><tbody><?php foreach($orders as $o):?><tr><td><a href="?id=<?= (int)$o['id'] ?>">№<?= (int)$o['id'] ?></a><small><?= e($o['created_at']) ?></small></td><td><?= e($o['customer_name']) ?><small><?= e($o['customer_contact']) ?></small></td><td><?= e(shop_money((int)$o['total_minor'],$o['currency']??'EUR')) ?></td><td><?= e($names[$o['status']]) ?></td></tr><?php endforeach ?><?php if(!$orders):?><tr><td colspan="4" class="empty">Заявок пока нет.</td></tr><?php endif ?></tbody></table></div><?php if($page>1):?><a href="?status=<?= e($status) ?>&amp;page=<?= $page-1 ?>">Назад</a><?php endif ?><?php if($page*50<$total):?><a href="?status=<?= e($status) ?>&amp;page=<?= $page+1 ?>">Далее</a><?php endif ?><?php endif ?><?php require __DIR__.'/shop-shell-end.php'; ?>
